void main (){
    const week = [ "Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота", "Воскресенье"];
    print(week);  // [Понедельник, Вторник, Среда, Четверг, Пятница, Суббота, Воскресенье]
